import { useState } from 'react';

export function Modal({ children }) {
  const [open, setOpen] = useState(false);
  return (
    <>
      <button onClick={() => setOpen(true)} className="rounded bg-blue-600 px-4 py-2 text-white">Open Modal</button>
      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50" onClick={() => setOpen(false)}>
          <div className="w-full max-w-md rounded-lg bg-white p-6 shadow-xl" onClick={(e) => e.stopPropagation()}>
            <h2 className="mb-4 text-xl font-semibold">{{title}}</h2>
            {children}
            <div className="mt-6 flex justify-end gap-2">
              <button onClick={() => setOpen(false)} className="rounded border px-4 py-2">Cancel</button>
              <button className="rounded bg-blue-600 px-4 py-2 text-white">Confirm</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}
